-- Initial schema: fan-out notification tables.
--
-- notification_messages  : 1 row per unique message payload (channel + content + priority).
--                          batch_id groups a batch upload; scheduled_at enables future delivery.
-- user_notifications     : per-recipient delivery row. Holds status, attempts, idempotency key.
-- fcm_tokens             : per-user device push tokens (multi-device fan-out).
--
-- All primary keys are UUIDv7 (k-sortable, time-ordered), generated by the app.

begin;

create table if not exists notification_messages (
    id           uuid primary key,
    batch_id     uuid null,
    channel      text not null check (channel in ('sms','email','push')),
    priority     text not null check (priority in ('high','normal','low')),
    content      jsonb not null,
    template_id  uuid null,
    scheduled_at timestamptz null,
    created_at   timestamptz not null default now()
);
create index if not exists idx_messages_batch   on notification_messages (batch_id) where batch_id is not null;
create index if not exists idx_messages_created on notification_messages (created_at desc);
create index if not exists idx_messages_scheduled on notification_messages (scheduled_at) where scheduled_at is not null;

create table if not exists user_notifications (
    id                  uuid primary key,
    message_id          uuid not null references notification_messages(id) on delete cascade,
    recipient           text not null,
    idempotency_key     text not null unique,
    status              text not null check (status in
                            ('pending','processing','sent','failed','canceled','dead_letter')),
    attempts            int  not null default 0,
    last_error          text null,
    provider_message_id text null,
    sent_at             timestamptz null,
    created_at          timestamptz not null default now(),
    updated_at          timestamptz not null default now()
);
create index if not exists idx_user_notif_message on user_notifications (message_id);
create index if not exists idx_user_notif_status  on user_notifications (status, created_at desc);
create index if not exists idx_user_notif_recipient on user_notifications (recipient);

create table if not exists fcm_tokens (
    id          uuid primary key,
    user_id     text not null,
    token       text not null,
    platform    text not null check (platform in ('ios','android','web')),
    device_name text null,
    created_at  timestamptz not null default now(),
    unique (user_id, token)
);
create index if not exists idx_fcm_tokens_user on fcm_tokens (user_id);

commit;
